# region: fold
def fold(raw):
    out = []
    for tok in raw:
        try:
            out.append(float(tok))
        except ValueError:
            pass
    return out

# region: shape
def shape(xs):
    return [v for v in xs if v % 2 == 0]

# region: gather
def gather(xs, offset=-1):
    return [v + offset for v in xs]

# region: render
def render(xs, offset=-1):
    return [v - offset for v in xs]

# region: emit
def emit(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: intake
def intake(summary):
    out = dict(summary)
    out['flags'] = sorted(k for k, v in summary.items() if isinstance(v, int) and v > 0)
    return out

# region: run
def run(raw):
    return intake(emit(render(gather(shape(fold(raw))))))

